43. function Normalize-Version {
44.     param([string]$Value)
45.     if ([string]::IsNullOrWhiteSpace($Value)) { return $null }
46.     $clean = $Value.Trim()
47.     $clean = $clean -replace '^[vV]', ''
48.     $clean = ($clean -split '[+ -]')[0]
49.     try { return [version]$clean } catch { return $null }
50. }
51. 
52. function Compare-Version {
53.     param(
54.         [string]$Actual,
55.         [string]$Minimum
56.     )
57.     $a = Normalize-Version $Actual
58.     $m = Normalize-Version $Minimum
59.     if (-not $a -or -not $m) { return $null }
60.     return ($a -ge $m)
61. }
62. 
63. function Get-CommandTextOutput {
64.     param(
65.         [string]$Name,
66.         [string[]]$CommandArgs = @()
67.     )
68.     try {
69.         $null = Get-Command $Name -ErrorAction Stop
70.         return (& $Name @CommandArgs 2>&1 | Out-String).Trim()
71.     } catch {
72.         return $null
73.     }
74. }
75. 
76. function Add-Result {
77.     param(
78.         [System.Collections.Generic.List[object]]$List,
79.         [string]$Category,
80.         [string]$Name,
81.         [string]$Installed,
82.         [string]$Required,
83.         [string]$Status,
84.         [string]$Notes
85.     )
86.     $List.Add([pscustomobject]@{
87.             Category  = $Category
88.             Name      = $Name
89.             Installed = $Installed
90.             Required  = $Required
91.             Status    = $Status
92.             Notes     = $Notes
93.         })
94. }
95. 
96. function Parse-VersionFromRegex {
97.     param(
98.         [string]$InputText,
99.         [string]$Pattern
100.     )
101.     if ([string]::IsNullOrWhiteSpace($InputText)) { return $null }
102.     $m = [regex]::Match($InputText, $Pattern)
103.     if ($m.Success -and $m.Groups.Count -gt 1) { return $m.Groups[1].Value.Trim() }
104.     return $null
105. }
106. 
107. function Remove-Ansi {
108.     param([string]$Text)
109.     if ($null -eq $Text) { return $null }
110.     return ($Text -replace '\x1B\[[0-9;?]*[ -/]*[@-~]', '')
111. }
112. 
113. function Get-PluginVersionFromLocalInstall {
114.     param([string]$PluginKey)
115. 
116.     $parts = $PluginKey.Split("@")
117.     if ($parts.Count -ne 2) { return $null }
118.     $pluginName = $parts[0]
119.     $marketplace = $parts[1]
120. 
121.     $root = Join-Path $env:USERPROFILE ".copilot\installed-plugins\$marketplace\$pluginName"
122.     if (-not (Test-Path $root)) { return $null }
123. 
124.     $jsonCandidates = Get-ChildItem $root -Recurse -Filter "plugin.json" -ErrorAction SilentlyContinue
125.     foreach ($file in $jsonCandidates) {
126.         try {
127.             $obj = Get-Content $file.FullName -Raw | ConvertFrom-Json
128.             if ($obj.name -eq $pluginName -and $obj.version) {
129.                 return [string]$obj.version
130.             }
131.         } catch {
132.             continue
133.         }
134.     }
135.     return $null
136. }
137. 
138. if ($FixGhAuth -and (Test-Path Env:GITHUB_TOKEN)) {
139.     Remove-Item Env:GITHUB_TOKEN -ErrorAction SilentlyContinue
140.     Write-Host "Removed GITHUB_TOKEN from current session environment."
141. }
142. 
143. if ($Setup) {
144.     Write-Host "Running update/setup actions..." -ForegroundColor Cyan
145. 
146.     $wingetIds = @(
147.         "Microsoft.AzureCLI",
148.         "Microsoft.Azd",
149.         "OpenJS.NodeJS.22",
150.         "GitHub.cli"
151.     )
152.     foreach ($id in $wingetIds) {
153.         try {
154.             Write-Host "winget upgrade $id"
155.             & winget upgrade --id $id --accept-package-agreements --accept-source-agreements 2>&1 | Out-Host
156.         } catch {
157.             Write-Warning "winget upgrade failed for ${id}: $($_.Exception.Message)"
158.         }
159.     }
160. 
161.     try {
162.         Write-Host "pac install latest"
163.         & pac install latest 2>&1 | Out-Host
164.     } catch {
165.         Write-Warning "pac install latest failed: $($_.Exception.Message)"
166.     }
167. 
168.     try {
169.         Write-Host "npm install -g @microsoft/dataverse@latest"
170.         & npm install -g @microsoft/dataverse@latest 2>&1 | Out-Host
171.     } catch {
172.         Write-Warning "Dataverse CLI npm update failed: $($_.Exception.Message)"
173.     }
174. 
175.     try {
176.         Write-Host "copilot plugin update --all"
177.         & copilot plugin update --all 2>&1 | Out-Host
178.     } catch {
179.         Write-Warning "Plugin update failed (often a lock issue if Copilot is open): $($_.Exception.Message)"
180.     }
181. }
182. 
183. $results = [System.Collections.Generic.List[object]]::new()
184. 
185. $requirements = @{
186.     "az"         = "2.88.0"
187.     "azd"        = "1.29.0"
188.     "node"       = "22.0.0"
189.     "npm"        = "11.0.0"
190.     "pac"        = "2.9.3"
191.     "dotnet"     = "8.0.0"
192.     "gh"         = "2.96.0"
193.     "gh-stack"   = "0.1.0"
194.     "dataverse"  = "1.0.59"
195.     "plugin-dv"  = "1.10.0"
196.     "plugin-cps" = "1.0.11"
197.     "plugin-cap" = "1.1.0"
198.     "plugin-pa"  = "2.3.1"
199.     "plugin-mcs" = "1.0.2"
200. }
201. 
202. $azRaw = Get-CommandTextOutput -Name "az" -CommandArgs @("version", "--output", "json")
203. $azVersion = $null
204. if ($azRaw) {
205.     try {
206.         $azObj = $azRaw | ConvertFrom-Json
207.         $azVersion = $azObj."azure-cli"
208.     } catch {
209.         $azVersion = Parse-VersionFromRegex -InputText $azRaw -Pattern 'azure-cli[^0-9]*([0-9]+\.[0-9]+\.[0-9]+)'
210.     }
211. }
212. 
213. $azdRaw = Get-CommandTextOutput -Name "azd" -CommandArgs @("version")
214. $azdVersion = Parse-VersionFromRegex -InputText $azdRaw -Pattern 'azd version ([0-9]+\.[0-9]+\.[0-9]+)'
215. 
216. $nodeRaw = Get-CommandTextOutput -Name "node" -CommandArgs @("--version")
217. $nodeVersion = if ($nodeRaw) { $nodeRaw.TrimStart('v') } else { $null }
218. 
219. $npmRaw = Get-CommandTextOutput -Name "npm" -CommandArgs @("--version")
220. $npmVersion = if ($npmRaw) { $npmRaw.Trim() } else { $null }
221. 
222. $pacRaw = Get-CommandTextOutput -Name "pac"
223. $pacVersion = Parse-VersionFromRegex -InputText $pacRaw -Pattern 'Version:\s*([0-9]+\.[0-9]+\.[0-9]+)'
224. 
225. $dotnetRaw = Get-CommandTextOutput -Name "dotnet" -CommandArgs @("--version")
226. $dotnetVersion = if ($dotnetRaw) { $dotnetRaw.Trim() } else { $null }
227. 
228. $ghRaw = Get-CommandTextOutput -Name "gh" -CommandArgs @("--version")
229. $ghVersion = Parse-VersionFromRegex -InputText $ghRaw -Pattern 'gh version ([0-9]+\.[0-9]+\.[0-9]+)'
230. 
231. $gitRaw = Get-CommandTextOutput -Name "git" -CommandArgs @("--version")
232. $gitVersion = Parse-VersionFromRegex -InputText $gitRaw -Pattern 'git version ([0-9]+\.[0-9]+\.[0-9]+)'
233. 
234. $ghExtRaw = Get-CommandTextOutput -Name "gh" -CommandArgs @("extension", "list")
235. $ghStackVersion = $null
236. if ($ghExtRaw) {
237.     $ghStackVersion = Parse-VersionFromRegex -InputText $ghExtRaw -Pattern 'gh stack\s+github/gh-stack\s+v([0-9]+\.[0-9]+\.[0-9]+)'
238. }
239. 
240. $dataverseInstalledRaw = Get-CommandTextOutput -Name "npm" -CommandArgs @("list", "-g", "@microsoft/dataverse", "--depth=0")
241. $dataverseInstalledVersion = Parse-VersionFromRegex -InputText $dataverseInstalledRaw -Pattern '@microsoft/dataverse@([0-9]+\.[0-9]+\.[0-9]+)'
242. 
243. $dataverseLatestRaw = Get-CommandTextOutput -Name "npm" -CommandArgs @("view", "@microsoft/dataverse", "version")
244. $dataverseLatestVersion = if ($dataverseLatestRaw) { $dataverseLatestRaw.Trim() } else { $null }
245. 
246. $copilotPluginsRaw = Get-CommandTextOutput -Name "copilot" -CommandArgs @("plugin", "list")
247. $plugins = @{}
248. if ($copilotPluginsRaw) {
249.     $normalizedCopilotPlugins = Remove-Ansi $copilotPluginsRaw
250.     # Be tolerant to terminal rendering differences (bullet glyph, asterisk, dash, or plain text).
251.     $matches = [regex]::Matches(
252.         $normalizedCopilotPlugins,
253.         '(?im)^\s*(?:[•\-\*]\s+)?([a-z0-9][a-z0-9\-]*)@([a-z0-9][a-z0-9\-]*)\s+\(v([0-9]+\.[0-9]+\.[0-9]+)\)\s*$'
254.     )
255.     if ($matches.Count -eq 0) {
256.         # Fallback to non-anchored scan in case the host injects extra prefix text per line.
257.         $matches = [regex]::Matches(
258.             $normalizedCopilotPlugins,
259.             '(?i)([a-z0-9][a-z0-9\-]*)@([a-z0-9][a-z0-9\-]*)\s+\(v([0-9]+\.[0-9]+\.[0-9]+)\)'
260.         )
261.     }
262.     foreach ($m in $matches) {
263.         $key = "$($m.Groups[1].Value)@$($m.Groups[2].Value)"
264.         $plugins[$key] = $m.Groups[3].Value
265.     }
266. }
267. 
268. $toolChecks = @(
269.     @{ Name = "az"; Installed = $azVersion; Required = $requirements.az; Category = "Tooling" },
270.     @{ Name = "azd"; Installed = $azdVersion; Required = $requirements.azd; Category = "Tooling" },
271.     @{ Name = "node"; Installed = $nodeVersion; Required = $requirements.node; Category = "Tooling" },
272.     @{ Name = "npm"; Installed = $npmVersion; Required = $requirements.npm; Category = "Tooling" },
273.     @{ Name = "pac"; Installed = $pacVersion; Required = $requirements.pac; Category = "Tooling" },
274.     @{ Name = "dotnet"; Installed = $dotnetVersion; Required = $requirements.dotnet; Category = "Tooling" },
275.     @{ Name = "gh"; Installed = $ghVersion; Required = $requirements.gh; Category = "Tooling" },
276.     @{ Name = "git"; Installed = $gitVersion; Required = "2.0.0"; Category = "Tooling" },
277.     @{ Name = "gh-stack"; Installed = $ghStackVersion; Required = $requirements."gh-stack"; Category = "Extensions" },
278.     @{ Name = "@microsoft/dataverse"; Installed = $dataverseInstalledVersion; Required = $requirements.dataverse; Category = "Tooling" }
279. )
280. 
281. foreach ($check in $toolChecks) {
282.     if ([string]::IsNullOrWhiteSpace($check.Installed)) {
283.         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed "-" -Required $check.Required -Status "FAIL" -Notes "Not detected"
284.         continue
285.     }
286.     $ok = Compare-Version -Actual $check.Installed -Minimum $check.Required
287.     if ($ok -eq $true) {
288.         $notes = ""
289.         if ($check.Name -eq "@microsoft/dataverse" -and $dataverseLatestVersion) {
290.             $notes = "latest=$dataverseLatestVersion"
291.         }
292.         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed $check.Installed -Required $check.Required -Status "OK" -Notes $notes
293.     } elseif ($ok -eq $false) {
294.         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed $check.Installed -Required $check.Required -Status "WARN" -Notes "Below recommended baseline"
295.     } else {
296.         Add-Result -List $results -Category $check.Category -Name $check.Name -Installed $check.Installed -Required $check.Required -Status "WARN" -Notes "Version parse issue"
297.     }
298. }
299. 
300. $pluginChecks = @(
301.     @{ Key = "dataverse@awesome-copilot"; Required = $requirements."plugin-dv" },
302.     @{ Key = "copilot-studio@skills-for-copilot-studio"; Required = $requirements."plugin-cps" },
303.     @{ Key = "code-apps-preview@power-platform-skills"; Required = $requirements."plugin-cap" },
304.     @{ Key = "power-automate@power-platform-skills"; Required = $requirements."plugin-pa" },
305.     @{ Key = "mcs-assistant@copilot-studio-plugin"; Required = $requirements."plugin-mcs" }
306. )
307. 
308. foreach ($p in $pluginChecks) {
309.     $installed = $null
310.     if ($plugins.ContainsKey($p.Key)) { $installed = $plugins[$p.Key] }
311.     if (-not $installed) { $installed = Get-PluginVersionFromLocalInstall -PluginKey $p.Key }
312.     if (-not $installed) {
313.         Add-Result -List $results -Category "Plugins" -Name $p.Key -Installed "-" -Required $p.Required -Status "FAIL" -Notes "Plugin not installed"
314.         continue
315.     }
316.     $ok = Compare-Version -Actual $installed -Minimum $p.Required
317.     $status = if ($ok -eq $true) { "OK" } else { "WARN" }
318.     $notes = if ($ok -eq $true) { "" } else { "Below recommended baseline" }
319.     Add-Result -List $results -Category "Plugins" -Name $p.Key -Installed $installed -Required $p.Required -Status $status -Notes $notes
320. }
321. 
322. if (Test-Path Env:GITHUB_TOKEN) {
323.     $ghAuth = Get-CommandTextOutput -Name "gh" -CommandArgs @("auth", "status")
324.     if ($ghAuth -and $ghAuth -match 'token in GITHUB_TOKEN is invalid') {
325.         Add-Result -List $results -Category "Auth" -Name "GITHUB_TOKEN precedence" -Installed "invalid env token detected" -Required "unset or valid token" -Status "WARN" -Notes "Run with -FixGhAuth or remove env var"
326.     }
327. }
328. 
329. if ($Json) {
330.     $results | ConvertTo-Json -Depth 4
331. } else {
332.     Write-Host ""
333.     Write-Host "Tech stack readiness report" -ForegroundColor Cyan
334.     Write-Host "=========================="
335.     $results | Sort-Object Category, Name | Format-Table -AutoSize
336. 
337.     $failCount = @($results | Where-Object { $_.Status -eq "FAIL" }).Count
338.     $warnCount = @($results | Where-Object { $_.Status -eq "WARN" }).Count
339.     Write-Host ""
340.     if ($failCount -eq 0 -and $warnCount -eq 0) {
341.         Write-Host "Result: READY" -ForegroundColor Green
342.     } elseif ($failCount -eq 0) {
343.         Write-Host "Result: READY WITH WARNINGS ($warnCount warning(s))" -ForegroundColor Yellow
344.     } else {
345.         Write-Host "Result: NOT READY ($failCount fail(s), $warnCount warning(s))" -ForegroundColor Red
346.     }
347. }
348.
